#include <vector>
#include <algorithm>

class Solution {
public:
    int maxIncreasingSubarrays(std::vector<int>& nums) {
        int n = nums.size();
        std::vector<int> runs;
        int curr = 1;
        for (int i = 1; i < n; ++i) {
            if (nums[i] > nums[i - 1]) {
                curr++;
            } else {
                runs.push_back(curr);
                curr = 1;
            }
        }
        runs.push_back(curr);

        int ans = 0;
        for (int L : runs) ans = std::max(ans, L / 2);
        for (int i = 0; i < (int)runs.size() - 1; ++i) {
            ans = std::max(ans, std::min(runs[i], runs[i + 1]));
        }
        return ans;
    }
};

import java.util.*;

class Solution {
    public int maxIncreasingSubarrays(List<Integer> nums) {
        int n = nums.size();
        List<Integer> runs = new ArrayList<>();
        int curr = 1;
        for (int i = 1; i < n; i++) {
            if (nums.get(i) > nums.get(i - 1)) {
                curr++;
            } else {
                runs.add(curr);
                curr = 1;
            }
        }
        runs.add(curr);

        int ans = 0;
        for (int L : runs) ans = Math.max(ans, L / 2);
        for (int i = 0; i < runs.size() - 1; i++) {
            ans = Math.max(ans, Math.min(runs.get(i), runs.get(i + 1)));
        }
        return ans;
    }
}

var maxIncreasingSubarrays = function(nums) {
    const n = nums.length;
    const runs = [];
    let curr = 1;
    for (let i = 1; i < n; i++) {
        if (nums[i] > nums[i - 1]) {
            curr++;
        } else {
            runs.push(curr);
            curr = 1;
        }
    }
    runs.push(curr);

    let ans = 0;
    for (const L of runs) ans = Math.max(ans, Math.floor(L / 2));
    for (let i = 0; i < runs.length - 1; i++) {
        ans = Math.max(ans, Math.min(runs[i], runs[i + 1]));
    }
    return ans;
};
